.dwu-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dwu-root,.dwu-root *,.dwu-root *::before,.dwu-root *::after{box-sizing:border-box}
.dwu-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dwu-root img{display:block;border:0;max-width:none}
.dwu-root > [data-node-id]{will-change:transform}
.dwu-root [hidden]{display:none!important}
.dwu-root [data-sh-theme="dark"]{display:none!important}
.dwu-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dwu-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dwu-root .n1_6944{align-content:stretch;display:flex;gap:6px;align-items:center;justify-content:center;padding-left:35px;padding-right:35px;padding-top:12px;padding-bottom:12px;position:relative;border-radius:15px;flex-shrink:0}
.dwu-root .n1_6944::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #d5d6dd);border-radius:15px;pointer-events:none}
.dwu-root .n1_6945{position:relative;flex-shrink:0;color:var(--wa-text, #171d25);width:70px;line-height:24px;white-space:nowrap}
.dwu-root .n1_6946{position:relative;flex-shrink:0;color:var(--wa-text-sub, #767676);width:9px;line-height:24px;white-space:nowrap}
.dwu-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.dwu-root[data-theme="dark"] [data-name="Header"] > [data-name="Background"]{background:var(--wa-bg, #131519)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.06)!important}
.dwu-root[data-theme="dark"] [data-name="Input"],.dwu-root[data-theme="dark"] [data-name="Select"],.dwu-root[data-theme="dark"] [data-name^="Field/ID"],.dwu-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
.dwu-root[data-theme="dark"] [data-name="Widget/Notice"] > div:first-child,.dwu-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:first-child,.dwu-root[data-theme="dark"] [data-name="Panel"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 64%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 76%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px) saturate(1.15)!important;-webkit-backdrop-filter:blur(18px) saturate(1.15)!important}
.dwu-root[data-theme="dark"] [data-name="Widget/Notice"] > div:nth-child(3),.dwu-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:nth-child(3),.dwu-root[data-theme="dark"] [data-name="Panel"] > div:nth-child(3){box-shadow:inset 0 1px 0 rgba(255,255,255,.1),inset 0 0 0 1px rgba(255,255,255,.07),0 24px 48px rgba(0,0,0,.34)!important}
.dwu-root[data-theme="dark"] > [data-node-id]:has([data-name^="Widget/"]) > [data-name="Header"] > [data-name="Background"]{background:color-mix(in srgb, var(--wa-bg, rgb(14 16 20)) 68%, transparent)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwu-root[data-theme="dark"] [data-name^="Step/"] > div:first-child{background-color:color-mix(in srgb, var(--wa-point, rgb(130 155 255)) 12%, transparent)}
.dwu-root[data-theme="dark"] [data-name^="Widget/"] [data-name="List Item/Post"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 4.5%, transparent)}
.dwu-root[data-theme="dark"] [data-name="Count"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent)!important}
.dwu-root[data-theme="dark"] [data-name="Login Card"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 62%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 74%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwu-root[data-theme="dark"] [data-name="Login Card"] > div:nth-child(2){box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 0 0 1px rgba(255,255,255,.08),0 30px 60px rgba(0,0,0,.4)!important}
.dwu-root[data-theme="dark"] [data-name="Search Overlay"] > [data-name="Background"],.dwu-root[data-theme="dark"] [data-name="Background"][data-node-id="1:6533"]{background-color:var(--wa-surface, #17191e)!important}
.dwu-root[data-theme="dark"] .n1_6944::after{border-color:var(--wa-line, #31343c)}
.dwu-root[data-theme="dark"] .n1_6945{color:var(--wa-text, #eceef2)}
.dwu-root[data-theme="dark"] .n1_6946{color:var(--wa-text-sub, #a7acb6)}
